class Solution:
    def visibleMountains(self, peaks):
        intervals = sorted([(p[0]-p[1], p[0]+p[1]) for p in peaks])
        ans = 0
        i = 0
        n = len(intervals)
        max_right = float('-inf')
        while i < n:
            j = i
            while j < n and intervals[j] == intervals[i]:
                j += 1
            count = j - i
            if intervals[i][1] > max_right:
                if count == 1:
                    ans += 1
                max_right = intervals[i][1]
            i = j
        return ans

