class Solution:
    def countExcellentPairs(self, nums, k):
        from collections import Counter
        bits = sorted(bin(x).count('1') for x in set(nums))
        ans = 0
        n = len(bits)
        l, r = 0, n - 1
        while l < n:
            while r >= 0 and bits[l] + bits[r] >= k:
                r -= 1
            ans += n - max(r + 1, l)
            l += 1
        # Use two pointer approach
        ans = 0
        j = n - 1
        for i in range(n):
            while j >= 0 and bits[i] + bits[j] >= k:
                j -= 1
            ans += n - j - 1
        return ans

class Solution:
    def maximumBooks(self, books):
        n = len(books)
        dp = [0] * n
        stk = []
        ans = 0
        for i in range(n):
            while stk and books[stk[-1]] - stk[-1] >= books[i] - i:
                stk.pop()
            j = stk[-1] if stk else -1
            length = i - j
            top = books[i]
