class Solution:
    def reachableNodes(self, n, edges, restricted):
        from collections import deque, defaultdict
        blocked = set(restricted)
        g = defaultdict(list)
        for u, v in edges:
            g[u].append(v)
            g[v].append(u)
        visited = {0}
        q = deque([0])
        while q:
            node = q.popleft()
            for nei in g[node]:
