class Solution:
    def countSpecialNumbers(self, n):
        s = str(n)
        from functools import lru_cache
        @lru_cache(maxsize=None)
        def dp(pos, mask, tight, started):
            if pos == len(s):
                return 1 if started else 0
            limit = int(s[pos]) if tight else 9
            res = 0
            if not started:
                res += dp(pos+1, mask, False, False)
                for d in range(1, limit+1):
                    res += dp(pos+1, mask|(1<<d), tight and d==limit, True)
            else:
                for d in range(0, limit+1):
                    if mask & (1<<d):
                        continue
                    res += dp(pos+1, mask|(1<<d), tight and d==limit, True)
            return res
        return dp(0, 0, True, False)

class Solution:
    def maxScore(self, edges):
        from collections import defaultdict
        g = defaultdict(list)
        n = len(edges)
        for i in range(1, n):
            p, w = edges[i]
            g[p].append((i, w))
        def dfs(u):
            # returns (not_pick_any_edge_from_u, pick_one_edge_from_u)
            s = 0  # sum of best(pick or not) of all children
            best_gain = 0
            for v, w in g[u]:
                np, p = dfs(v)
                s += max(np, p)
                best_gain = max(best_gain, w + np - max(np, p))
            return s, s + best_gain
        np, p = dfs(0)
        return max(np, p)

