class Solution:
    def shiftingLetters(self, s, shifts):
        n = len(s)
        diff = [0] * (n + 1)
        for start, end, direction in shifts:
            d = 1 if direction == 1 else -1
            diff[start] += d
            diff[end+1] -= d
        cur = 0
        res = list(s)
        for i in range(n):
            cur += diff[i]
            res[i] = chr((ord(s[i]) - ord('a') + cur) % 26 + ord('a'))
        return ''.join(res)

