class Solution:
    def amountOfTime(self, root, start):
        from collections import defaultdict, deque
        g = defaultdict(list)
        def build(node, parent):
            if not node:
                return
            if parent:
                g[node.val].append(parent.val)
                g[parent.val].append(node.val)
            build(node.left, node)
            build(node.right, node)
        build(root, None)
        visited = {start}
        q = deque([start])
        time = -1
        while q:
            time += 1
            for _ in range(len(q)):
                node = q.popleft()
                for nei in g[node]:
                    if nei not in visited:
                        visited.add(nei)
                        q.append(nei)
        return time

class Solution:
    def matrixMedian(self, grid):
        import bisect
        m, n = len(grid), len(grid[0])
        total = m * n
        lo, hi = grid[0][0], grid[0][-1]
        for row in grid:
            lo = min(lo, row[0])
            hi = max(hi, row[-1])
        while lo < hi:
            mid = (lo + hi) // 2
            cnt = sum(bisect.bisect_right(row, mid) for row in grid)
            if cnt < (total + 1) // 2:
                lo = mid + 1
            else:
                hi = mid
        return lo

