class Solution:
    def buildMatrix(self, k, rowConditions, colConditions):
        from collections import deque, defaultdict
        def topo_sort(k, edges):
            g = defaultdict(list)
            indeg = [0] * (k + 1)
            for u, v in edges:
                g[u].append(v)
                indeg[v] += 1
            q = deque(i for i in range(1, k+1) if indeg[i] == 0)
            order = []
            while q:
                u = q.popleft()
                order.append(u)
                for v in g[u]:
                    indeg[v] -= 1
                    if indeg[v] == 0:
                        q.append(v)
            return order if len(order) == k else []
        row_order = topo_sort(k, rowConditions)
        col_order = topo_sort(k, colConditions)
        if not row_order or not col_order:
            return []
        row_pos = {v: i for i, v in enumerate(row_order)}
        col_pos = {v: i for i, v in enumerate(col_order)}
        mat = [[0]*k for _ in range(k)]
        for num in range(1, k+1):
            mat[row_pos[num]][col_pos[num]] = num
        return mat

