class Solution:
    def maximumRobots(self, chargeTimes, runningCosts, budget):
        from collections import deque
        n = len(chargeTimes)
        dq = deque()
        total = 0
        ans = 0
        l = 0
        for r in range(n):
            while dq and chargeTimes[dq[-1]] <= chargeTimes[r]:
                dq.pop()
            dq.append(r)
            total += runningCosts[r]
            while dq and chargeTimes[dq[0]] + (r - l + 1) * total > budget:
                if dq[0] == l:
                    dq.popleft()
                total -= runningCosts[l]
                l += 1
            ans = max(ans, r - l + 1)
        return ans

