class Solution:
    def numberOfWays(self, startPos, endPos, k):
        MOD = 10**9 + 7
        d = abs(endPos - startPos)
        if (k + d) % 2 != 0 or k < d:
            return 0
        r = (k + d) // 2
        from math import comb
        return comb(k, r) % MOD
